    let b = commit(&repo, "b", Some(a));
    let c = commit(&repo, "c", Some(b));
    let mut walk = repo.revwalk().unwrap();
    walk.push_range(&format!("{b}..{c}")).unwrap();
    let got: Vec<Oid> = walk.collect::<Result<_, _>>().unwrap();
    assert_eq!(got, [c]);
